function retryFor(pattern: string, fullAnswer: string, correctAnswer: string): [TriText, TriText, TriText, TriText] {
  return [
    tri(
      `Сначала посмотри вправо от пропуска. Твой ориентир: ${pattern}.`,
      `Спочатку подивись праворуч від пропуску. Твій орієнтир: ${pattern}.`,
      `Primero mira a la derecha del hueco. Tu guia: ${pattern}.`,
      {
        'pt-BR': `Primeiro olhe à direita da lacuna. Sua referência: ${pattern}.`,
        vi: `Trước hết nhìn sang bên phải chỗ trống. Mốc của bạn: ${pattern}.`,
        id: `Pertama lihat ke kanan bagian kosong. Panduanmu: ${pattern}.`,
        tr: `Önce boşluğun sağına bak. İpucun: ${pattern}.`,
        pl: `Najpierw spójrz w prawo od luki. Twój punkt odniesienia: ${pattern}.`,
      },
    ),
    tri(
      'Если после пропуска сразу есть предмет, выбирай короткое слово. Если предмета после нет, выбирай слово, которое стоит одно.',
      'Якщо після пропуску одразу є предмет, обирай коротке слово. Якщо предмета після немає, обирай слово, яке стоїть саме.',
      'Si despues del hueco viene la cosa, elige la palabra corta. Si no viene la cosa, elige la palabra que va sola.',
      {
        'pt-BR': 'Se depois da lacuna vem logo o objeto, escolha a palavra curta. Se não vem objeto depois, escolha a palavra que fica sozinha.',
        vi: 'Nếu sau chỗ trống có ngay đồ vật, chọn từ ngắn. Nếu sau đó không có đồ vật, chọn từ đứng một mình.',
        id: 'Jika setelah bagian kosong langsung ada benda, pilih kata pendek. Jika tidak ada benda setelahnya, pilih kata yang berdiri sendiri.',
        tr: 'Boşluktan hemen sonra nesne varsa kısa kelimeyi seç. Sonra nesne yoksa tek başına duran kelimeyi seç.',
        pl: 'Jeśli po luce od razu jest rzecz, wybierz krótkie słowo. Jeśli po niej nie ma rzeczy, wybierz słowo, które stoi samo.',
      },
    ),
    tri(
      `Собери фразу целиком: ${fullAnswer}`,
      `Збери фразу повністю: ${fullAnswer}`,
      `Arma la frase completa: ${fullAnswer}`,
      {
        'pt-BR': `Monte a frase inteira: ${fullAnswer}`,
        vi: `Ghép cả câu: ${fullAnswer}`,
        id: `Susun kalimat lengkap: ${fullAnswer}`,
        tr: `Cümlenin tamamını kur: ${fullAnswer}`,
        pl: `Złóż całe zdanie: ${fullAnswer}`,
      },
    ),
    tri(
      `Почти подсказка: выбери "${correctAnswer}".`,
      `Майже підказка: обери "${correctAnswer}".`,
      `Casi pista: elige "${correctAnswer}".`,
      {
        'pt-BR': `Quase uma dica: escolha "${correctAnswer}".`,
        vi: `Gần như gợi ý: chọn "${correctAnswer}".`,
        id: `Hampir petunjuk: pilih "${correctAnswer}".`,
        tr: `Neredeyse ipucu: "${correctAnswer}" seç.`,
        pl: `Prawie podpowiedź: wybierz "${correctAnswer}".`,
      },
    ),
  ];
}

function possessiveStep(input: StepInput): DiagnosisTrainingStep {
  const correctIndex = input.options.findIndex((option) => option === input.correctAnswer);
  const wrongFeedbackByOption = Object.fromEntries(
    input.options
      .filter((option) => option !== input.correctAnswer)
      .map((option) => [
        option,
        input.wrong[option] ?? tri(
          `Почти. "${option}" не подходит именно в этом месте. Проверь, есть ли предмет сразу после пропуска.`,
          `Майже. "${option}" не підходить саме в цьому місці. Перевір, чи є предмет одразу після пропуску.`,
          `Casi. "${option}" no encaja en este lugar. Mira si hay una cosa justo despues del hueco.`,
          {
            'pt-BR': `Quase. "${option}" não encaixa exatamente neste lugar. Verifique se há um objeto logo depois da lacuna.`,
            vi: `Gần đúng. "${option}" không hợp đúng vị trí này. Kiểm tra xem có đồ vật ngay sau chỗ trống không.`,
            id: `Hampir. "${option}" tidak cocok tepat di tempat ini. Periksa apakah ada benda langsung setelah bagian kosong.`,
            tr: `Neredeyse. "${option}" tam bu yerde uymaz. Boşluktan hemen sonra nesne var mı kontrol et.`,
            pl: `Prawie. "${option}" nie pasuje dokładnie w tym miejscu. Sprawdź, czy zaraz po luce jest rzecz.`,
          },
        ),
      ]),
  ) as Record<string, TriText>;

  return {
    id: input.id,
    order: input.order,
    difficulty: input.difficulty,
    type: 'single_choice',
    targetSkill: input.targetSkill,
    translation: input.translation,
    explanationBlock: sharedExplanation,
    microTask: tri(
      'Выбери слово для значения "чей / чья / чьё / чьи".',
      'Обери слово для значення "чий / чия / чиє / чиї".',
      'Elige la palabra para decir de quien es.',
      {
        'pt-BR': 'Escolha a palavra para o sentido de "de quem é".',
        vi: 'Chọn từ cho nghĩa "của ai".',
        id: 'Pilih kata untuk makna "milik siapa".',
        tr: '"Kimin" anlamı için kelimeyi seç.',
        pl: 'Wybierz słowo dla znaczenia "czyj/czyja/czyje".',
      },
    ),
    sentence: input.sentence,
    answerOptions: input.options.map((text) => ({ id: text, text })),
    correctAnswerId: input.correctAnswer,
    correctIndex,
    correctFeedback: input.correctFeedback,
    wrongFeedbackByOption,
    retryFeedback: retryFor(input.pattern, input.fullAnswer, input.correctAnswer),
    fallbackExplanation: tri(
      `Запомни короткую пару: ${input.pattern}. Если справа есть предмет, слово стоит перед ним. Если предмета справа нет, слово заменяет весь кусок.`,
      `Запам'ятай коротку пару: ${input.pattern}. Якщо праворуч є предмет, слово стоїть перед ним. Якщо предмета праворуч немає, слово замінює весь зворот.`,
      `Recuerda el par corto: ${input.pattern}. Si a la derecha hay una cosa, la palabra va antes. Si no hay cosa a la derecha, la palabra reemplaza todo el bloque.`,
      {
        'pt-BR': `Lembre o par curto: ${input.pattern}. Se à direita há um objeto, a palavra fica antes dele. Se não há objeto à direita, a palavra substitui todo o bloco.`,
        vi: `Nhớ cặp ngắn: ${input.pattern}. Nếu bên phải có đồ vật, từ đứng trước nó. Nếu bên phải không có đồ vật, từ thay thế cả cụm.`,
        id: `Ingat pasangan pendek: ${input.pattern}. Jika di kanan ada benda, kata itu berdiri sebelum benda tersebut. Jika tidak ada benda di kanan, kata itu menggantikan seluruh potongan.`,
        tr: `Kısa çifti hatırla: ${input.pattern}. Sağda nesne varsa kelime onun önünde durur. Sağda nesne yoksa kelime tüm parçanın yerine geçer.`,
        pl: `Zapamiętaj krótką parę: ${input.pattern}. Jeśli po prawej jest rzecz, słowo stoi przed nią. Jeśli po prawej nie ma rzeczy, słowo zastępuje cały fragment.`,
      },
    ),
    focusWords: input.focusWords,
  };
}

